"""Separate JFR allocation sensitivity reports; never replace the raw summaries.

Omit the first allocation sample for each recorded thread ID, before applying
the existing summary filters. OpenJDK 25 starts each recording with a zero
last-sample counter, so the first sample can represent pre-recording allocations.
This is an approximate corrected distribution, not exact allocation accounting:
the omitted sample also contains some allocations after recording began.
CPU events pass through unchanged. JMH gc.alloc.rate.norm remains the source
for absolute allocation per operation. Inputs must be chronological JFR JSON
exports containing the beginning of each recording.
"""

import argparse
import json
from pathlib import Path
import re
import sys

from summarize_jfr import (ALLOCATION_EVENT, DEFAULT_STACK, DEFAULT_THREAD,
                           class_name, iter_jfr_events, markdown, method_key,
                           percent, summarize)


JDK_SOURCE = "https://github.com/openjdk/jdk25u/blob/fda231468e56663992785ec199a6efb8eca3cc7a/"


def without_initial_allocations(events, omitted, thread_regex, stack_regex):
    seen = set()
    thread_pattern, stack_pattern = re.compile(thread_regex), re.compile(stack_regex)
    for event in events:
        if event.get("type") == ALLOCATION_EVENT:
            values = event.get("values")
            if not isinstance(values, dict):
                raise ValueError("Allocation sample has no values object")
            thread = values.get("eventThread") or {}
            key = next(((field, thread[field]) for field in ("javaThreadId", "osThreadId")
                        if isinstance(thread.get(field), int) and not isinstance(thread[field], bool)
                        and thread[field] > 0), None)
            if key is None:
                raise ValueError("Allocation sample has no usable recorded thread ID; refusing to merge unknown threads")
            if key not in seen:
                seen.add(key)
                weight = values.get("weight")
                if isinstance(weight, bool) or not isinstance(weight, int) or weight < 0:
                    raise ValueError(f"Invalid allocation sample weight: {weight!r}")
                methods = [method_key(frame) for frame in (values.get("stackTrace") or {}).get("frames", [])]
                name = thread.get("javaName") or thread.get("osName") or "<unknown thread>"
                omitted.append({
                    "thread_id_field": key[0], "thread_id": key[1], "thread": thread,
                    "start_time": values.get("startTime"), "weight_bytes": weight,
                    "class": class_name(values.get("objectClass")),
                    "method": methods[0][0] if methods else None,
                    "descriptor": methods[0][1] if methods else None,
                    "stack": [{"method": method, "descriptor": descriptor} for method, descriptor in methods],
                    "selected_by_existing_filters": bool(thread_pattern.search(name))
                    or any(stack_pattern.search(method[0]) for method in methods),
                })
                continue
        yield event


def steady_report(path, thread_regex, stack_regex):
    omitted = []
    report = summarize(without_initial_allocations(iter_jfr_events(path), omitted,
                                                  thread_regex, stack_regex), thread_regex, stack_regex)
    selected_omitted = [sample for sample in omitted if sample["selected_by_existing_filters"]]
    allocation = report["allocation"]
    total_omitted_weight = sum(sample["weight_bytes"] for sample in omitted)
    selected_omitted_weight = sum(sample["weight_bytes"] for sample in selected_omitted)
    raw_selected_weight = allocation["filtered_weight_bytes"] + selected_omitted_weight
    report["input"] = str(path.resolve())
    report["allocation_adjustment"] = {
        "method": "omit first allocation sample per recorded thread ID in input order, before filtering",
        "interpretation": "approximate corrected distribution; a sensitivity analysis, not exact byte accounting",
        "cpu_events_changed": False,
        "raw_total_allocation_samples": allocation["total_samples"] + len(omitted),
        "raw_selected_allocation_samples": allocation["filtered_samples"] + len(selected_omitted),
        "raw_total_allocation_weight_bytes": allocation["total_weight_bytes"] + total_omitted_weight,
        "raw_selected_allocation_weight_bytes": raw_selected_weight,
        "omitted_total_samples": len(omitted), "omitted_selected_samples": len(selected_omitted),
        "omitted_total_weight_bytes": total_omitted_weight,
        "omitted_selected_weight_bytes": selected_omitted_weight,
        "omitted_selected_weight_percent_of_raw": percent(selected_omitted_weight, raw_selected_weight),
        "omitted_samples": omitted,
        "primary_sources": [
            JDK_SOURCE + "src/hotspot/share/jfr/support/jfrObjectAllocationSample.cpp#L32-L55",
            JDK_SOURCE + "src/hotspot/share/jfr/support/jfrThreadLocal.hpp#L244-L254",
            JDK_SOURCE + "src/hotspot/share/jfr/recorder/service/jfrRecorderService.cpp#L454-L479",
            JDK_SOURCE + "src/hotspot/share/runtime/thread.hpp#L258-L260",
        ],
    }
    report["notes"] = [note for note in report["notes"] if not note.startswith("All matching events")]
    report["notes"] += [
        "This separate sensitivity report omits each thread's first allocation sample; raw recordings and summaries remain authoritative evidence.",
        "OpenJDK's first allocation sample can carry cumulative pre-recording weight; omission also discards some valid post-start allocations.",
        "Remaining allocation attribution is sampled and throttled, not exact; totals are not normalized by rows or iterations.",
        "CPU events and JMH results are unchanged; use JMH gc.alloc.rate.norm for measured absolute B/row.",
        "The same first-sample caveat applies to the previous round's allocation percentages from this profiler, without changing its CPU or JMH results.",
    ]
    return report


def steady_markdown(report, top):
    adjustment = report["allocation_adjustment"]
    lines = ["# JFR allocation first-sample sensitivity analysis", "",
             "Approximate corrected distribution: the first allocation sample per recorded thread ID is omitted. "
             "This also drops some valid post-start allocation weight. CPU events are unchanged; "
             "JMH remains the authority for measured B/row. Keep the raw summary alongside this report.", "",
             f"Omitted selected allocation weight: {adjustment['omitted_selected_weight_bytes']:,} bytes "
             f"({adjustment['omitted_selected_weight_percent_of_raw']:.2f}% of the raw selected weight).", "",
             "## Every omitted allocation sample", "",
             "| Thread ID | Timestamp | Weight, bytes | Selected | Allocated class | Top recorded frame |",
             "| --- | --- | ---: | --- | --- | --- |"]
    for sample in adjustment["omitted_samples"]:
        site = (sample["method"] or "<no stack>") + (sample["descriptor"] or "")
        site = site.replace("|", "\\|").replace("`", "'")
        lines.append(f"| {sample['thread_id_field']}={sample['thread_id']} | {sample['start_time']} | "
                     f"{sample['weight_bytes']:,} | {sample['selected_by_existing_filters']} | "
                     f"`{sample['class']}` | `{site}` |")
    lines.extend(["", markdown(report, top).replace("# JFR binary writer profile summary",
                                                   "## Retained-event summary", 1)])
    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("inputs", nargs="+", type=Path)
    parser.add_argument("--top", type=int, default=25)
    parser.add_argument("--thread-regex", default=DEFAULT_THREAD)
    parser.add_argument("--stack-regex", default=DEFAULT_STACK)
    args = parser.parse_args()
    if args.top < 1:
        parser.error("--top must be positive")
    try:
        for path in args.inputs:
            report = steady_report(path, args.thread_regex, args.stack_regex)
            stem = path.stem.removesuffix(".events")
            json_path = path.with_name(stem + ".steady-summary.json")
            markdown_path = path.with_name(stem + ".steady-summary.md")
            if path.resolve() in (json_path.resolve(), markdown_path.resolve()):
                raise ValueError("Input and output paths must be distinct")
            json_path.write_text(json.dumps(report, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
            markdown_path.write_text(steady_markdown(report, args.top), encoding="utf-8")
            print(f"{path.name}: omitted {report['allocation_adjustment']['omitted_total_samples']} initial samples; "
                  f"wrote {json_path.name} and {markdown_path.name}")
    except (OSError, ValueError, re.error) as failure:
        print(f"JFR sensitivity summary failed: {failure}", file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
